use std::fmt;
use std::fs::File;
use std::io::{self, Read};

// ---- Custom error type ----
#[derive(Debug)]
enum GameError {
    Io(io::Error),
    InvalidData(String),
    PlayerNotFound(String),
    NotEnoughGold { needed: i32, available: i32 },
}

impl fmt::Display for GameError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            GameError::Io(e) => write!(f, "I/O error: {}", e),
            GameError::InvalidData(msg) => write!(f, "Invalid data: {}", msg),
            GameError::PlayerNotFound(name) => write!(f, "Player '{}' not found", name),
            GameError::NotEnoughGold { needed, available } => {
                write!(f, "Not enough gold! Need {}, have {}", needed, available)
            }
        }
    }
}

impl std::error::Error for GameError {}

// ---- Conversion from io::Error ----
impl From<io::Error> for GameError {
    fn from(err: io::Error) -> Self {
        GameError::Io(err)
    }
}

// ---- Functions that use custom errors ----
fn load_player_file(name: &str) -> Result<String, GameError> {
    let filename = format!("{}.txt", name);
    let mut file = File::open(&filename)?;  // Converts io::Error to GameError
    let mut contents = String::new();
    file.read_to_string(&mut contents)?;
    Ok(contents)
}

fn parse_player_data(data: &str) -> Result<Player, GameError> {
    let lines: Vec<&str> = data.lines().collect();
    if lines.len() < 3 {
        return Err(GameError::InvalidData("Not enough lines".to_string()));
    }

    let name = lines[0].trim();
    let health = lines[1].trim().parse()
        .map_err(|_| GameError::InvalidData("Invalid health".to_string()))?;
    let attack = lines[2].trim().parse()
        .map_err(|_| GameError::InvalidData("Invalid attack".to_string()))?;

    Ok(Player {
        name: name.to_string(),
        health,
        attack,
    })
}

#[derive(Debug)]
struct Player {
    name: String,
    health: i32,
    attack: i32,
}

fn get_player(name: &str) -> Result<Player, GameError> {
    let data = load_player_file(name)?;
    parse_player_data(&data)
}

fn process_player(name: &str) -> Result<Player, GameError> {
    // Use ? to propagate errors
    let player = get_player(name)?;

    if player.health <= 0 {
        return Err(GameError::InvalidData("Player has no health".to_string()));
    }

    Ok(player)
}

fn main() {
    // ---- Using custom errors ----
    match process_player("Hero") {
        Ok(player) => println!("Player: {} (HP: {}, ATK: {})", player.name, player.health, player.attack),
        Err(e) => println!("Error: {}", e),
    }

    // ---- Testing error handling ----
    match process_player("Gandalf") {
        Ok(player) => println!("Player: {}", player.name),
        Err(GameError::PlayerNotFound(name)) => println!("Player '{}' not found", name),
        Err(e) => println!("Error: {}", e),
    }

    // ---- Creating custom errors ----
    let error1 = GameError::NotEnoughGold { needed: 100, available: 50 };
    println!("Error: {}", error1);

    let error2 = GameError::PlayerNotFound("Legolas".to_string());
    println!("Error: {}", error2);
}

// ---- Result alias ----
type GameResult<T> = Result<T, GameError>;

fn get_player_with_alias(name: &str) -> GameResult<Player> {
    let data = load_player_file(name)?;
    parse_player_data(&data)
}

